base.expression:
// extract out the base rating contribution to the base stat to get the true base (baseAdj)
const base = GetStat(GetOwner(), $#10516612381411111:6064628617716498440$);
const baseRating = GetStat(GetInstigator(), $#10516612381411111:6064628617716695052$);
const baseCoeff = EvalE($#10516612381411112:6064633702542016513$);
const baseAdj = base / (1.0 - baseRating / (baseRating + baseCoeff));

// calculate total rating including the base rating but reduced by the coefficient quotient
const coeff = EvalE($#10516612381411112:6064630400815923201$);
const rating = baseRating * coeff/baseCoeff + GetStat(GetInstigator(), $#10516612381411111:109183607133840$);

// calc final stat value
baseAdj * (1.0 - rating / (rating + coeff))
